// dout_vld
always @(posedge clk) begin
    if (reset == 1'b1)
        dout_vld <= 1'b0;
    else if (pop)
        dout_vld <= 1'b1;
    else if (if_read_ce & if_read)
        dout_vld <= 1'b0;
end

