module MUX_GEMM_MUX (
        ap_clk,
        ap_rst,
        ap_start,
        ap_done,
        ap_continue,
        ap_idle,
        ap_ready,
        xmq_buffered_stream_dout,
        xmq_buffered_stream_num_data_valid,
        xmq_buffered_stream_fifo_cap,
